-- HR-портал: раздел «Индивидуальный план развития». PostgreSQL 18.
-- Выполнять после подключения к новой базе hr_ipr.
-- Сначала создаются таблицы, затем внешние ключи, индексы и тестовые данные.
-- Скрипт рассчитан на пустую базу. Удаление пользователей запрещено;
-- применяется логическая деактивация (is_active = false).

BEGIN;

-- 1. Таблицы и ограничения данных.
CREATE TABLE "department" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL,
  CONSTRAINT "ck_department_name" CHECK (btrim(name) <> '')
);

CREATE TABLE "app_user" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "full_name" varchar(150) NOT NULL,
  "email" varchar(254) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "role" varchar(20) NOT NULL,
  "department_id" integer NOT NULL,
  "manager_id" integer,
  "is_active" boolean NOT NULL DEFAULT true,
  "deactivated_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_app_user_full_name" CHECK (btrim(full_name) <> ''),
  CONSTRAINT "ck_app_user_email" CHECK (email = lower(btrim(email)) AND email <> ''),
  CONSTRAINT "ck_app_user_password_hash" CHECK (btrim(password_hash) <> ''),
  CONSTRAINT "ck_app_user_role" CHECK (role IN ('employee', 'manager', 'hr')),
  CONSTRAINT "ck_app_user_manager" CHECK (manager_id IS NULL OR manager_id <> id)
);

CREATE TABLE "competency" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar(100) UNIQUE NOT NULL,
  "description" text,
  CONSTRAINT "ck_competency_name" CHECK (btrim(name) <> '')
);

CREATE TABLE "development_plan" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "employee_id" integer NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'draft',
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "manager_comment" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "ck_development_plan_status" CHECK (status IN ('draft', 'pending', 'approved', 'rejected', 'completed')),
  CONSTRAINT "ck_development_plan_dates" CHECK (end_date >= start_date),
  CONSTRAINT "ck_development_plan_rejection" CHECK (status <> 'rejected' OR (manager_comment IS NOT NULL AND btrim(manager_comment) <> ''))
);

CREATE TABLE "goal" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "plan_id" integer NOT NULL,
  "description" text NOT NULL,
  "deadline" date NOT NULL,
  CONSTRAINT "ck_goal_description" CHECK (btrim(description) <> '')
);

CREATE TABLE "activity" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "goal_id" integer NOT NULL,
  "type" varchar(20) NOT NULL,
  "description" text NOT NULL,
  "deadline" date NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'planned',
  "completion_date" date,
  CONSTRAINT "ck_activity_type" CHECK (type IN ('course', 'practice', 'reading')),
  CONSTRAINT "ck_activity_description" CHECK (btrim(description) <> ''),
  CONSTRAINT "ck_activity_status" CHECK (status IN ('planned', 'completed')),
  CONSTRAINT "ck_activity_completion" CHECK ((status = 'completed' AND completion_date IS NOT NULL) OR (status = 'planned' AND completion_date IS NULL))
);

CREATE TABLE "plan_competency" (
  "plan_id" integer NOT NULL,
  "competency_id" integer NOT NULL,
  "current_level" integer NOT NULL,
  "target_level" integer NOT NULL,
  CONSTRAINT "ck_plan_competency_current" CHECK (current_level BETWEEN 1 AND 5),
  CONSTRAINT "ck_plan_competency_target" CHECK (target_level BETWEEN 1 AND 5),
  CONSTRAINT "ck_plan_competency_growth" CHECK (target_level >= current_level),
  PRIMARY KEY ("plan_id", "competency_id")
);

-- 2. Внешние ключи.
ALTER TABLE "app_user" ADD CONSTRAINT "fk_app_user_department_id" FOREIGN KEY ("department_id") REFERENCES "department" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "app_user" ADD CONSTRAINT "fk_app_user_manager_id" FOREIGN KEY ("manager_id") REFERENCES "app_user" ("id") ON DELETE SET NULL ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "development_plan" ADD CONSTRAINT "fk_development_plan_employee_id" FOREIGN KEY ("employee_id") REFERENCES "app_user" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "goal" ADD CONSTRAINT "fk_goal_plan_id" FOREIGN KEY ("plan_id") REFERENCES "development_plan" ("id") ON DELETE CASCADE ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "activity" ADD CONSTRAINT "fk_activity_goal_id" FOREIGN KEY ("goal_id") REFERENCES "goal" ("id") ON DELETE CASCADE ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "plan_competency" ADD CONSTRAINT "fk_plan_competency_plan_id" FOREIGN KEY ("plan_id") REFERENCES "development_plan" ("id") ON DELETE CASCADE ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "plan_competency" ADD CONSTRAINT "fk_plan_competency_competency_id" FOREIGN KEY ("competency_id") REFERENCES "competency" ("id") ON DELETE RESTRICT ON UPDATE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

-- 3. Индексы для отбора планов и перехода к связанным данным.
CREATE INDEX "idx_app_user_active" ON "app_user" ("is_active");
CREATE INDEX "idx_app_user_department" ON "app_user" ("department_id");
CREATE INDEX "idx_app_user_manager" ON "app_user" ("manager_id");
CREATE INDEX "idx_development_plan_employee" ON "development_plan" ("employee_id");
CREATE INDEX "idx_development_plan_status" ON "development_plan" ("status");
CREATE INDEX "idx_goal_plan" ON "goal" ("plan_id");
CREATE INDEX "idx_activity_goal" ON "activity" ("goal_id");
CREATE INDEX "idx_plan_competency_competency" ON "plan_competency" ("competency_id");

-- 4. Учебные данные. Все имена и адреса вымышлены.
